# Using the FastMCP-style decorator API (names vary by SDK version).
from mcp.server.fastmcp import FastMCP

mcp = FastMCP("support-server")

@mcp.tool()
def create_ticket(title: str, priority: str = "low") -> str:
    """Create a support ticket. priority is low|medium|high."""
    # the type hints become the tool's input JSON Schema:
    #   {"title": {"type": "string"}, "priority": {"type": "string"}}
    ticket_id = _db_insert(title=title, priority=priority)
    return f"created ticket {ticket_id}"   # content returned to the client

