# A conceptual, SDK-free model of the JSON-RPC layer MCP rides on.
TOOLS = {
    "create_ticket": {
        "inputSchema": {"type": "object",
                        "properties": {"title": {"type": "string"}},
                        "required": ["title"]},
        "handler": lambda title: f"created ticket for {title!r}",
    }
}

def handle(request: dict) -> dict:
    rid, method, params = request["id"], request["method"], request.get("params", {})
    if method == "tools/list":
        listed = [{"name": n, "inputSchema": t["inputSchema"]} for n, t in TOOLS.items()]
        return {"jsonrpc": "2.0", "id": rid, "result": {"tools": listed}}
    if method == "tools/call":
        tool = TOOLS[params["name"]]
        text = tool["handler"](**params["arguments"])
        return {"jsonrpc": "2.0", "id": rid,
                "result": {"content": [{"type": "text", "text": text}]}}
    return {"jsonrpc": "2.0", "id": rid,
            "error": {"code": -32601, "message": "method not found"}}

print(handle({"jsonrpc": "2.0", "id": 1, "method": "tools/list", "params": {}}))
print(handle({"jsonrpc": "2.0", "id": 2, "method": "tools/call",
              "params": {"name": "create_ticket", "arguments": {"title": "Bug"}}}))

