def dispatch(request: dict, tools: dict) -> dict:
    rid = request["id"]
    method = request["method"]
    params = request.get("params", {})
    base = {"jsonrpc": "2.0", "id": rid}

    if method == "tools/list":
        listed = [{"name": name} for name in tools]
        return {**base, "result": {"tools": listed}}

    if method == "tools/call":
        fn = tools[params["name"]]
        text = str(fn(**params.get("arguments", {})))
        return {**base, "result": {"content": [{"type": "text", "text": text}]}}

    # unknown method -> standard JSON-RPC 'method not found' error
    return {**base, "error": {"code": -32601, "message": "method not found"}}

