def build_tools_list(registry: dict, request_id: int = 1) -> dict:
    # registry maps tool name -> {"description": str, "inputSchema": dict}
    tools = []
    for name, spec in registry.items():
        tools.append({
            "name": name,
            "description": spec.get("description", ""),
            "inputSchema": spec.get("inputSchema", {"type": "object"}),
        })
    return {
        "jsonrpc": "2.0",
        "id": request_id,
        "result": {"tools": tools},
    }

if __name__ == "__main__":
    registry = {
        "create_ticket": {
            "description": "Create a support ticket.",
            "inputSchema": {
                "type": "object",
                "properties": {"title": {"type": "string"}},
                "required": ["title"],
            },
        }
    }
    resp = build_tools_list(registry, request_id=7)
    print(resp["id"], resp["result"]["tools"][0]["name"])

